import sys; sys.path.insert(0, '_tools'); from spec import enrich
enrich('los-ojos-del-interior', 'A',
 [dict(t=600, e=655, titulo='Un tiempo para rasgar', txt='Rasgar es romper algo, pero sin violencia, porque si no sería desgarrar. Entonces, esta palabra «rasgar» es uno de los veintiocho tiempos que cada uno de nosotros vive a lo largo de su vida. Tal vez vivimos uno antes que otro, pero vamos a vivir todos estos tiempos.'),
  dict(t=1051, e=1100, titulo='De adentro hacia afuera', txt='Pero vea los seres vivientes: ellos tenían ojos por dentro, dice primero. Pero a veces, ¿qué vemos primero? Lo de afuera. Vemos la paja que tiene nuestro hermano en su ojo y no vemos, dice la Biblia, la viga que nosotros tenemos. […] Es como el versículo anterior que leímos: su corazón estaba dentro y después sus vestidos, por fuera. O sea, de adentro hacia afuera nosotros vamos a cambiar. Si no, sería legalismo.'),
  dict(t=3423, e=3468, titulo='Tienes nombre de que vives', txt='«Yo conozco tus obras, que tienes nombre de que vives, pero estás muerto». Entonces, aquí, ¿qué hay? Una apariencia. Mire, hermano, yo puedo aparentar que me siento bien y no me siento bien. Yo puedo aparentar que estoy en santidad y no estoy en santidad. Puedo aparentar muchas cosas, porque dice ahí: «Tienes nombre de que vives, pero estás muerto». Puro sepulcro.')],
 [dict(t=1245, txt='No deberíamos hacer las cosas a medias, porque si las hacemos a medias, primero Dios no va a recibir esa ofrenda.'),
  dict(t=2450, txt='«Sé fiel hasta la muerte, y yo te daré la corona de la vida».'),
  dict(t=4350, txt='El Señor está tocando a la puerta, y si tú abres, él entra, y tú cenarás con él y él contigo.')],
 ['¿Qué parte de tu vida se ve bien por fuera pero necesita que Dios la toque primero por dentro?',
  'Si tuvieras que rasgar hoy el corazón y no los vestidos, ¿qué le dirías al Señor con sinceridad?',
  '¿Hay algo que estás haciendo «a medias» delante de Dios y que esta semana puedes entregarle completo?'])
